def transform(grid):
    h, w = len(grid), len(grid[0])

    # The palette is the nonzero sequence on a row repeated several times.
    row_counts = {}
    for row in grid:
        seq = tuple(v for v in row if v != 0)
        if len(seq) > 1:
            row_counts[seq] = row_counts.get(seq, 0) + 1
    palette = max(row_counts, key=lambda s: row_counts[s])

    # Extract the silhouette made of color 1 and its bounding box.
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    shape = {(r-r0, c-c0) for r, c in cells}
    sh = r1 - r0 + 1

    # Keep the original-colored copy in its original location.
    idx = palette.index(1)
    top = r0 - idx * sh
    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        for dr, dc in shape:
            rr, cc = top + i * sh + dr, c0 + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
